parameters.jsCode:
const details = $('Appointment details extractor').first().json.output;

const requestedDate = details.Date;
const requestedTime = details.Time;

// Create the requested starting date and time
const requestedStart = DateTime.fromISO(
  `${requestedDate}T${requestedTime}`,
  { zone: 'Asia/Kolkata' }
);

if (!requestedStart.isValid) {
  throw new Error(
    `Invalid appointment date or time: ${requestedDate} ${requestedTime}`
  );
}

// Generate the next six possible 30-minute slots
const slots = [];

for (let i = 1; i <= 6; i++) {
  const start = requestedStart.plus({ minutes: 30 * i });
  const end = start.plus({ minutes: 30 });

  slots.push({
    json: {
      slotNumber: i,
      start: start.toISO(),
      end: end.toISO(),
      displayDate: start.toFormat('dd LLLL yyyy'),
      displayTime: start.toFormat('hh:mm a'),
    },
  });
}

return slots;

const availableResults = $input.all();

const originalSlots = $('Generate Alternative Slots').all();

const availableSlots = availableResults
  .map((result, index) => {
    return {
      available: result.json.available,
      ...originalSlots[index].json,
    };
  })
  .filter(slot => slot.available === true)
  .slice(0, 3);

const details = $('Appointment details extractor').first().json.output;

const alternativesHtml = availableSlots
  .map((slot, index) => `
    <li>
      <strong>Option ${index + 1}:</strong>
      ${slot.displayDate} at ${slot.displayTime}
    </li>
  `)
  .join('');

return [
  {
    json: {
      patientName: details.Name || 'there',
      requestedDate: details.Date || '',
      requestedTime: details.Time || '',
      alternativesFound: availableSlots.length > 0,
      alternativesHtml,
    },
  },
];
